package com.report.orderreport.controller;

import com.report.orderreport.model.ScheduleConfig;
import com.report.orderreport.service.ExternalScheduler;
import com.report.orderreport.service.ScheduleConfigService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;

import java.time.LocalDate;

@RestController
@RequestMapping(path = "/schedule")
public class SchedulingController {

    @Autowired
    ExternalScheduler externalScheduler;

    @Autowired
    ScheduleConfigService scheduleConfigService;

    @PostMapping("/addjob")
    @ResponseBody
    public String addJob(@RequestParam String name) {
        String cronExpression = scheduleConfigService.findConfigExpression(name);
        boolean result = externalScheduler.addJob(name,cronExpression);
        if (result) {
            return "Job successfully scheduled!";
        }
        return "There is already a job running for the specified name!";
    }

    @PostMapping("/removejob")
    @ResponseBody
    public String removeJob(@RequestParam String name) {
        boolean result = externalScheduler.removeJob(name);
        if (result) {
            return "Job successfully removed!";
        }
        return "There is no such job running!";
    }

    @PostMapping(path="/addconfig", consumes = "application/json", produces="application/json")
    @ResponseBody
    public String addConfig(@RequestBody ScheduleConfig scheduleConfig) {
        scheduleConfigService.addConfig(scheduleConfig);
        return "Done";
    }
}

